// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 timestamp1, uint256 timestamp2, uint256 blockNumber) public {
        vm.assume(timestamp1 < timestamp2);
        vm.assume(blockNumber % 15 != 0);
        timestamp1 = bound(timestamp1, 1, type(uint256).max - 1);
        timestamp2 = bound(timestamp2, timestamp1 + 1, type(uint256).max);

        address actor = address(0x1234);
        vm.deal(actor, 20 ether);

        vm.roll(blockNumber);
        vm.warp(timestamp1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "First call should succeed");

        vm.warp(timestamp2);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok2, "Second call should succeed");

        assertTrue(c.pastBlockTime() == timestamp2, "pastBlockTime must equal the last call's timestamp");
    }
}
